    """Sign a per-round revocation of one assess-evidence sample.

    ``sample`` must be a single-round :class:`Evidence` instance or its
    canonical :meth:`Evidence.to_bytes` encoding — exactly the kind of value
    carried as an :class:`AssessEvidence` sample; an :class:`AssessEvidence`
    itself, a :class:`Measurement` or any other kind is rejected, as is a
    malformed or non-canonical encoding or an invalid record. ``key`` must be
    non-empty ``bytes`` and ``revoked_at`` a finite non-bool non-negative
    number (``version`` is set to ``1``).

    The signed record is a :class:`BoundEvidenceRevocation` — the same
    per-round revocation record :func:`revoke_bound` mints, with the same
    ``NPBR1`` MAC over ``(round_index, nonce, revoked_at)`` taken from the
    sample — so it feeds both :func:`audit_assess_evidence_policy` and the
    existing :func:`audit_bound_policy` revocation sets interchangeably.
    Every violation, regardless of whether it is a shape or a value
    violation, raises :class:`ValueError`. Signing is pure computation: it
    reads and mutates no verifier state.
    """
    if not isinstance(key, bytes):
        raise ValueError("key must be non-empty bytes")
    if not key:
        raise ValueError("key must be non-empty")
    try:
        blob = _coerce_assess_evidence_sample(sample)
    except TypeError as error:
        raise ValueError(
            "sample must be an Evidence instance or its canonical bytes"
        ) from error
    evidence = Evidence.from_bytes(blob)
    record = BoundEvidenceRevocation(
        version=1,
        round_index=evidence.round_index,
        nonce=evidence.nonce,
        revoked_at=revoked_at,  # type: ignore[arg-type]
        mac=b"\x00" * 32,
    )
    return replace(
        record, mac=_bound_revocation_mac(key, _bound_revocation_payload(record))
    )


def _evidence_revocation_list_payload(
    erl: "EvidenceRevocationList",
) -> dict:
    """The JSON-ready evidence-revocation-list fields except ``mac``.

    ``entries`` is encoded as a JSON array of objects, each carrying exactly
    the :class:`BoundEvidenceRevocation` key set in its own field order,
    each entry's own ``NPBR1`` MAC included as lowercase hex.
    """
    return {
        "version": erl.version,
        "sequence": erl.sequence,
        "issued_at": erl.issued_at,
        "entries": [
            {**_bound_revocation_payload(entry), "mac": entry.mac.hex()}
            for entry in erl.entries
        ],
    }


def _evidence_revocation_list_mac(key: bytes, payload: dict) -> bytes:
    """HMAC-SHA256 over ``b"NPERL1"`` plus the canonical encoding without ``mac``.

    The prefix and the encoding are concatenated directly, with no separator
    or length prefix.
    """
    return hmac.new(
        key,
        _EVIDENCE_REVOCATION_LIST_PREFIX + _encode_payload(payload),
        hashlib.sha256,
    ).digest()


@dataclass(frozen=True)
class EvidenceRevocationList:
    """A MAC'd, distributable snapshot list of per-round evidence revocations.

    ``version`` is always ``1``; ``sequence`` a non-bool unsigned 64-bit
    integer; ``issued_at`` a finite non-bool non-negative number, stored as
    ``float``; ``entries`` a tuple of :class:`BoundEvidenceRevocation`
    instances — the same per-round revocation records
    :func:`revoke_bound` and :func:`revoke_evidence` sign — sorted ascending
    by ``(round_index, nonce)`` with no duplicate pair; ``mac`` exactly 32
    bytes — ``HMAC-SHA256(key, b"NPERL1" + encoding)`` over the canonical
    encoding of every field except ``mac`` itself (entries as an object
    array carrying their own ``NPBR1`` MACs), the prefix and the encoding
    concatenated directly with no length prefix. A field of the wrong type
    raises :class:`TypeError` at construction time; a value contract
    violation (including a non-sorted or duplicate entry tuple) raises
    :class:`ValueError`. Instances are frozen, constructed positionally in
    field order and compare equal by their fields. No key material is
    stored.
    """

    version: int
    sequence: int
    issued_at: float
    entries: "tuple[BoundEvidenceRevocation, ...]"
    mac: bytes

    def __post_init__(self) -> None:
        if type(self.version) is not int:
            raise TypeError("evidence revocation list version must be an integer")
        if self.version != 1:
            raise ValueError("evidence revocation list version must be 1")
        if isinstance(self.sequence, bool) or type(self.sequence) is not int:
            raise TypeError("evidence revocation list sequence must be an integer")
        if not 0 <= self.sequence <= 0xFFFFFFFFFFFFFFFF:
            raise ValueError(
                "evidence revocation list sequence must fit in an unsigned"
                " 64-bit integer"
            )
        value = self.issued_at
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(
                "evidence revocation list issued_at must be a finite non-negative"
                " number"
            )
        if not math.isfinite(value) or value < 0:
            raise ValueError(
                "evidence revocation list issued_at must be a finite non-negative"
                " number"
            )
        # The canonical encoding always spells issued_at as a float.
        object.__setattr__(self, "issued_at", float(value))
        if not isinstance(self.entries, tuple):
            raise TypeError(
                "evidence revocation list entries must be a tuple of"
                " BoundEvidenceRevocation"
            )
        previous = None
        for entry in self.entries:
            if not isinstance(entry, BoundEvidenceRevocation):
                raise TypeError(
                    "evidence revocation list entries must contain only"
                    " BoundEvidenceRevocation instances"
                )
            pair = (entry.round_index, entry.nonce)
            if previous is not None and pair <= previous:
                raise ValueError(
                    "evidence revocation list entries must be sorted by"
                    " (round_index, nonce) with no duplicates"
                )
            previous = pair
        if not isinstance(self.mac, bytes):
            raise TypeError("evidence revocation list mac must be bytes")
        if len(self.mac) != 32:
            raise ValueError("evidence revocation list mac must be exactly 32 bytes")

    def to_bytes(self) -> bytes:
        """Encode as compact UTF-8 JSON: keys in field order, ``entries`` as
        an array of objects with the bound-evidence-revocation keys in field
        order, ``issued_at`` as a float, every byte field as lowercase hex,
        no whitespace, no length prefix, no NaN/Infinity."""
        payload = _evidence_revocation_list_payload(self)
        payload["mac"] = self.mac.hex()
        return _encode_payload(payload)

    @classmethod
    def from_bytes(cls, data: bytes) -> "EvidenceRevocationList":
        """Decode :meth:`to_bytes` output, enforcing the field contract.

        Raises :class:`TypeError` for anything that is not ``bytes``; raises
        :class:`ValueError` for anything that does not satisfy the contract:
        exactly the list fields appearing once each in field order (missing,
        extra, duplicated or out-of-order keys are rejected, likewise inside
        every nested entry object), ``version == 1``, a non-bool u64
        ``sequence``, a finite non-bool non-negative ``issued_at`` stored as
        ``float``, an ``entries`` array of objects satisfying the
        :class:`BoundEvidenceRevocation` contract, sorted by
        ``(round_index, nonce)`` with no duplicate pair, and ``mac`` a
        lowercase hex string decoding to exactly 32 bytes. After parsing and
        field validation the record is re-encoded with :meth:`to_bytes` and
        the result must equal the input byte for byte, so formatted JSON,
        whitespace and any non-canonical number or string spelling are
        rejected as well. Neither the list MAC nor any entry MAC is verified
        here — use :func:`audit_evidence_revocation_list` with the shared
        key for that.
        """
        if not isinstance(data, bytes):
            raise TypeError("evidence revocation list data must be bytes")
        try:
            obj = json.loads(data, cls=_OrderedBoundEvidenceObject)
        except ValueError as error:
            raise ValueError(
                f"evidence revocation list is not valid JSON: {error}"
            ) from error
        if not isinstance(obj, dict) or list(obj) != list(
            _EVIDENCE_REVOCATION_LIST_FIELDS
        ):
            raise ValueError(
                "evidence revocation list must be a JSON object with exactly"
                " the evidence revocation list fields"
            )
        version = _parse_int_field(obj["version"], "version")
        if version != 1:
            raise ValueError("evidence revocation list version must be 1")
        sequence = _parse_int_field(obj["sequence"], "sequence")
        if not 0 <= sequence <= 0xFFFFFFFFFFFFFFFF:
            raise ValueError(
                "evidence revocation list sequence must fit in an unsigned"
                " 64-bit integer"
            )
        issued_at = obj["issued_at"]
        if isinstance(issued_at, bool) or not isinstance(issued_at, (int, float)):
            raise ValueError(
                "evidence revocation list issued_at must be a finite non-negative"
                " number"
            )
        if not math.isfinite(issued_at) or issued_at < 0:
            raise ValueError(
                "evidence revocation list issued_at must be a finite non-negative"
                " number"
            )
        raw_entries = obj["entries"]
        if not isinstance(raw_entries, list):
            raise ValueError(
                "evidence revocation list entries must be an array of objects"
            )
        entries: list[BoundEvidenceRevocation] = []
        for raw_entry in raw_entries:
            if not isinstance(raw_entry, dict) or list(raw_entry) != list(
                _BOUND_REVOCATION_FIELDS
            ):
                raise ValueError(
                    "evidence revocation list entries must be JSON objects with"
                    " exactly the bound evidence revocation fields"
                )
            try:
                entry = BoundEvidenceRevocation(
                    version=raw_entry["version"],
                    round_index=raw_entry["round_index"],
                    nonce=_parse_hex_field(raw_entry["nonce"], "nonce"),
                    revoked_at=raw_entry["revoked_at"],
                    mac=_parse_hex_field(raw_entry["mac"], "mac"),
                )
            except TypeError as error:
                # A nested entry of the right key set but the wrong field
                # shape makes the whole list encoding non-canonical; the
                # only TypeError this method raises is for non-bytes data.
                raise ValueError(
                    "evidence revocation list entry does not satisfy the"
                    " bound evidence revocation contract"
                ) from error
            entries.append(entry)
        mac = _parse_hex_field(obj["mac"], "mac")
        if len(mac) != 32:
            raise ValueError(
                "evidence revocation list mac must decode to exactly 32 bytes"
            )
        record = cls(
            version=version,
            sequence=sequence,
            issued_at=issued_at,
            entries=tuple(entries),
            mac=mac,
        )
        if record.to_bytes() != data:
            # Same canonical-encoding rule as the other records: no
            # whitespace, pretty-printing, framing or non-canonical
            # number/string spellings (including an integer issued_at, which
            # the float spelling would not reproduce).
            raise ValueError("evidence revocation list encoding is not canonical")
        return record


def make_evidence_revocation_list(
    entries: object,
    sequence: object,
    issued_at: object,
    key: object,
) -> EvidenceRevocationList:
    """Sign a snapshot list of per-round evidence revocations under ``key``.

    ``entries`` is an iterable of :class:`BoundEvidenceRevocation` instances
    (bytes encodings are not accepted here); it may be empty. The entries
    are copied into a tuple sorted ascending by ``(round_index, nonce)``,
    and a duplicate pair raises :class:`ValueError`. The entries' own
    ``NPBR1`` MACs are carried through unchanged. ``sequence`` must be a
    non-bool unsigned 64-bit integer and ``issued_at`` a finite non-bool
    non-negative number (stored as ``float``); a bool or a value of the
    wrong type raises :class:`TypeError`, an out-of-range or
    non-finite/negative value raises :class:`ValueError`. ``key`` must be
    non-empty ``bytes`` — a non-bytes value raises :class:`TypeError`, an
    empty value :class:`ValueError`. The returned
    :class:`EvidenceRevocationList` has ``version`` set to ``1`` and
    ``mac = HMAC-SHA256(key, b"NPERL1" + encoding)`` over the canonical
    encoding of every field except ``mac`` itself, the prefix and the
    encoding concatenated directly with no length prefix. Signing is pure
    data: it reads and mutates no challenge registry or consumption state.
    """
    if not isinstance(key, bytes):
        raise TypeError("key must be bytes")
    if not key:
        raise ValueError("key must be non-empty")
    try:
        raw_entries = list(entries)  # type: ignore[arg-type]
    except TypeError as error:
        raise TypeError(
            "entries must be an iterable of BoundEvidenceRevocation"
        ) from error
    for entry in raw_entries:
        if not isinstance(entry, BoundEvidenceRevocation):
            raise TypeError(
                "entries must contain only BoundEvidenceRevocation instances"
            )
    ordered = sorted(
        raw_entries, key=lambda entry: (entry.round_index, entry.nonce)
    )
    record = EvidenceRevocationList(
        version=1,
        sequence=sequence,  # type: ignore[arg-type]
        issued_at=issued_at,  # type: ignore[arg-type]
        entries=tuple(ordered),
        mac=b"\x00" * 32,
    )
    return replace(
        record,
        mac=_evidence_revocation_list_mac(
            key, _evidence_revocation_list_payload(record)
        ),
    )


def audit_evidence_revocation_list(
    x: "EvidenceRevocationList | bytes",
    key: object,
    now: object,
    min: object = 0,
) -> None:
    """Authenticate an :class:`EvidenceRevocationList` snapshot and check
    freshness.

    Accepts the list itself or its canonical
    :meth:`EvidenceRevocationList.to_bytes` encoding; anything else raises
    :class:`TypeError`, and bytes that do not parse raise
    :class:`ValueError`. ``key`` must be non-empty ``bytes`` (a non-bytes
    value raises :class:`TypeError`, an empty value :class:`ValueError`);
    ``now`` must be a finite non-bool number and ``min`` a non-bool integer
    (default ``0``); both violations raise :class:`ValueError`. Two MAC
    layers are recomputed with ``key`` and each compared in constant time:
    the list MAC is
    ``HMAC-SHA256(key, b"NPERL1" + encoding)`` over the canonical encoding
    of every field except the list ``mac``, and every entry's MAC is
    ``HMAC-SHA256(key, b"NPBR1" + encoding)`` exactly as
    :func:`audit_assess_evidence_policy` verifies it; a mismatch on either
    layer raises :class:`ValueError`. The snapshot must also be current:
    ``issued_at > now`` (a future-dated list) or ``sequence < min`` raises
    :class:`ValueError`. The check is pure: it returns ``None`` on success
    and touches no challenge registry or consumption state, and it is no
    substitute for verification-time replay protection.
    """
    if not isinstance(key, bytes):
        raise TypeError("key must be bytes")
    if not key:
        raise ValueError("key must be non-empty")
    if isinstance(x, bytes):
        erl = EvidenceRevocationList.from_bytes(x)
    elif isinstance(x, EvidenceRevocationList):
        erl = x
    else:
        raise TypeError(
            "evidence revocation list must be an EvidenceRevocationList"
            " instance or bytes"
        )
    if isinstance(now, bool) or not isinstance(now, (int, float)):
        raise ValueError("now must be a finite number")
    current = float(now)
    if not math.isfinite(current):
        raise ValueError("now must be a finite number")
    if isinstance(min, bool) or type(min) is not int:
        raise ValueError("min must be an integer")
    if not hmac.compare_digest(
        _evidence_revocation_list_mac(
            key, _evidence_revocation_list_payload(erl)
        ),
        erl.mac,
    ):
        raise ValueError("evidence revocation list mac does not match")
    for entry in erl.entries:
        if not hmac.compare_digest(
            _bound_revocation_mac(key, _bound_revocation_payload(entry)),
            entry.mac,
        ):
            raise ValueError(
                "bound evidence revocation mac does not match:"
                f" round {entry.round_index}"
            )
    if erl.issued_at > current:
        raise ValueError("evidence revocation list is dated in the future")
    if erl.sequence < min:
        raise ValueError("evidence revocation list sequence is below the minimum")


def _evidence_revocation_list_state_payload(
    state: "EvidenceRevocationListState",
) -> dict:
    """The JSON-ready evidence-revocation-list-state fields except ``mac``."""
    return {
        "version": state.version,
        "sequence": state.sequence,
        "digest": state.digest.hex(),
    }


def _evidence_revocation_list_state_mac(key: bytes, payload: dict) -> bytes:
    """HMAC-SHA256 over ``b"NPES1"`` plus the canonical encoding without ``mac``.

    The prefix and the encoding are concatenated directly with no separator
    or length prefix.
    """
    return hmac.new(
        key,
        _EVIDENCE_REVOCATION_LIST_STATE_PREFIX + _encode_payload(payload),
        hashlib.sha256,
    ).digest()


def _parse_evidence_revocation_list_state_hex(value: object, name: str) -> bytes:
    # Same lowercase, round-tripping hex rule as the other records.
    if not isinstance(value, str):
        raise ValueError(
            f"evidence revocation list state {name} must be a lowercase hex"
            " string"
        )
    try:
        raw = bytes.fromhex(value)
    except ValueError as error:
        raise ValueError(
            f"evidence revocation list state {name} must be a lowercase hex"
            " string"
        ) from error
    if raw.hex() != value:
        # Rejects uppercase digits, separators and odd-length input that
        # bytes.fromhex would otherwise tolerate.
        raise ValueError(
            f"evidence revocation list state {name} must be a lowercase hex"
            " string"
        )
    return raw


class _OrderedEvidenceRevocationListStateObject(json.JSONDecoder):
    """JSON decoder rejecting duplicate/out-of-order state object keys."""

    def __init__(self) -> None:
        super().__init__(object_pairs_hook=self._check_pairs)

    @staticmethod
    def _check_pairs(pairs: list) -> dict:
        keys = [key for key, _value in pairs]
        if keys == list(_EVIDENCE_REVOCATION_LIST_STATE_FIELDS):
            return dict(pairs)
        raise ValueError(
            "evidence revocation list state JSON keys must be exactly"
            " version, sequence, digest and mac in field order"
        )


@dataclass(frozen=True)
class EvidenceRevocationListState:
    """A key-MAC'd, rollback-resistant checkpoint of the audited
    evidence-revocation-list frontier.

    ``version`` is always ``1``; ``sequence`` a non-bool unsigned 64-bit
    integer (the accepted :class:`EvidenceRevocationList` sequence);
    ``digest`` exactly 32 bytes — ``SHA256(erl)`` over the canonical
    :meth:`EvidenceRevocationList.to_bytes` bytes of the accepted snapshot,
    binding the frontier to that one definite snapshot rather than any other
    snapshot carrying the same sequence; ``mac`` exactly 32 bytes —
    ``HMAC-SHA256(key, b"NPES1" + encoding)`` over the canonical encoding
    of every field except ``mac`` itself, the prefix and the encoding
    concatenated directly with no separator or length prefix. A field of
    the wrong type raises :class:`TypeError` at construction time; a value
    contract violation raises :class:`ValueError`. Instances are frozen,
    constructed positionally in field order and compare equal by their
    fields. No key material is stored.
    """

    version: int
    sequence: int
    digest: bytes
    mac: bytes

    def __post_init__(self) -> None:
        if type(self.version) is not int:
            raise TypeError(
                "evidence revocation list state version must be an integer"
            )
        if self.version != 1:
            raise ValueError("evidence revocation list state version must be 1")
        if isinstance(self.sequence, bool) or type(self.sequence) is not int:
            raise TypeError(
                "evidence revocation list state sequence must be a non-bool"
                " integer"
            )
        if not 0 <= self.sequence <= 0xFFFFFFFFFFFFFFFF:
            raise ValueError(
                "evidence revocation list state sequence must fit in an"
                " unsigned 64-bit integer"
            )
        for name in ("digest", "mac"):
            value = getattr(self, name)
            if not isinstance(value, bytes):
                raise TypeError(
                    f"evidence revocation list state {name} must be bytes"
                )
            if len(value) != 32:
                raise ValueError(
                    f"evidence revocation list state {name} must be exactly 32"
                    " bytes"
                )

    def to_bytes(self) -> bytes:
        """Encode as compact UTF-8 JSON: keys in field order, ``digest`` and
        ``mac`` as lowercase hex, no whitespace, no length prefix."""
        payload = _evidence_revocation_list_state_payload(self)
        payload["mac"] = self.mac.hex()
        return _encode_payload(payload)

    @classmethod
    def from_bytes(cls, data: bytes) -> "EvidenceRevocationListState":
        """Decode :meth:`to_bytes` output, enforcing the field contract.

        Raises :class:`TypeError` for anything that is not ``bytes``; raises
        :class:`ValueError` for anything that does not satisfy the contract:
        an object with exactly the keys ``version, sequence, digest, mac``
        once each in that order (missing, extra, duplicated or out-of-order
        keys are rejected), ``version == 1``, a non-bool u64 ``sequence``,
        and ``digest``/``mac`` lowercase hex strings decoding to exactly 32
        bytes each. After parsing and field validation the record is
        re-encoded with :meth:`to_bytes` and the result must equal the input
        byte for byte, so formatted JSON, whitespace and any non-canonical
        number or string spelling are rejected as well. The MAC is not
        verified here — pass the encoding to
        :class:`EvidenceRevocationListAuditor` (or recompute
        :func:`_evidence_revocation_list_state_mac` with the key) for that.
        """
        if not isinstance(data, bytes):
            raise TypeError(
                "evidence revocation list state data must be bytes"
            )
        try:
            obj = json.loads(data, cls=_OrderedEvidenceRevocationListStateObject)
        except ValueError as error:
            raise ValueError(
                f"evidence revocation list state is not valid JSON: {error}"
            ) from error
        if not isinstance(obj, dict) or list(obj) != list(
            _EVIDENCE_REVOCATION_LIST_STATE_FIELDS
        ):
            raise ValueError(
                "evidence revocation list state must be a JSON object with"
                " exactly the version, sequence, digest and mac fields in"
                " field order"
            )
        version = _parse_int_field(obj["version"], "version")
        if version != 1:
            raise ValueError("evidence revocation list state version must be 1")
        sequence = _parse_int_field(obj["sequence"], "sequence")
        if not 0 <= sequence <= 0xFFFFFFFFFFFFFFFF:
            raise ValueError(
                "evidence revocation list state sequence must fit in an"
                " unsigned 64-bit integer"
            )
        digest = _parse_evidence_revocation_list_state_hex(obj["digest"], "digest")
        if len(digest) != 32:
            raise ValueError(
                "evidence revocation list state digest must decode to exactly"
                " 32 bytes"
            )
        mac = _parse_evidence_revocation_list_state_hex(obj["mac"], "mac")
        if len(mac) != 32:
            raise ValueError(
                "evidence revocation list state mac must decode to exactly 32"
                " bytes"
            )
        record = cls(version=version, sequence=sequence, digest=digest, mac=mac)
        if record.to_bytes() != data:
            # Same canonical-encoding rule as the other records: no
            # whitespace, pretty-printing, framing or non-canonical
            # number/string spellings.
            raise ValueError(
                "evidence revocation list state encoding is not canonical"
            )
        return record


class EvidenceRevocationListAuditor:
    """Stateful :class:`EvidenceRevocationList` auditor that refuses snapshot
    sequence rollback.

    ``key`` must be non-empty ``bytes`` — a non-bytes value raises
    :class:`TypeError`, an empty value :class:`ValueError`; it is the same
    shared key the snapshots and checkpoints are MAC'd with. ``checkpoint``
    is keyword-only: ``None`` (the default) starts from the empty state;
    otherwise it must be an :class:`EvidenceRevocationListState` or its
    canonical :meth:`EvidenceRevocationListState.to_bytes` encoding, and its
    MAC is recomputed with ``key`` and compared in constant time (a
    malformed encoding or MAC mismatch raises :class:`ValueError`). Across a
    restart the caller must pass the value previously exported at
    :attr:`checkpoint`; nothing is persisted by the auditor itself.

    Each :meth:`audit` accepts an :class:`EvidenceRevocationList` or its
    canonical bytes and runs, under a single lock, the same two-layer
    stateless review as :func:`audit_evidence_revocation_list` — the list
    ``NPERL1`` MAC and every entry's ``NPBR1`` MAC in constant time, plus
    the ``issued_at <= now`` freshness and ``sequence >= min`` floor checks
    — and only then gates the snapshot against the checkpoint: a lower
    sequence is rejected, an equal sequence is accepted solely as a replay
    of the identical snapshot digest (a different snapshot at the same
    sequence is rejected), and a higher sequence advances the checkpoint.
    The verify, gate and update are one atomic critical section, so a
    rejected snapshot never changes the checkpoint and concurrent audits
    are linearized in lock-acquisition order with the accepted frontier
    never lost or moved backwards. A carried sequence outside the unsigned
    64-bit range cannot reach the gate (the snapshot or state record
    contract rejects it), so such an overflow attempt raises
    :class:`ValueError` before the checkpoint changes. Field-shape errors
    raise :class:`TypeError`; every other failure — an empty key, a
    malformed or non-canonical encoding, a MAC mismatch, a future snapshot,
    a sequence below the floor or checkpoint, a same-sequence/
    different-digest snapshot, an out-of-range sequence, or a tampered
    checkpoint — raises :class:`ValueError`.
    """

    def __init__(self, key: object, *, checkpoint: object = None) -> None:
        if not isinstance(key, bytes):
            raise TypeError("key must be bytes")
        if not key:
            raise ValueError("key must be non-empty")
        self._key = key
        self._lock = threading.Lock()
        self._state: "Optional[EvidenceRevocationListState]" = None
        if checkpoint is None:
            return
        if isinstance(checkpoint, EvidenceRevocationListState):
            state = checkpoint
        elif isinstance(checkpoint, bytes):
            state = EvidenceRevocationListState.from_bytes(checkpoint)
        else:
            raise TypeError(
                "checkpoint must be an EvidenceRevocationListState instance,"
                " its canonical bytes, or None"
            )
        if not hmac.compare_digest(
            _evidence_revocation_list_state_mac(
                self._key, _evidence_revocation_list_state_payload(state)
            ),
            state.mac,
        ):
            raise ValueError("checkpoint mac does not match the key")
        self._state = state

    @property
    def checkpoint(self) -> "Optional[EvidenceRevocationListState]":
        """The current frontier :class:`EvidenceRevocationListState`, or
        ``None`` before the first successfully audited snapshot. The
        returned object is frozen and the property read-only; persist its
        :meth:`EvidenceRevocationListState.to_bytes` output and pass it back
        to a new auditor to survive a restart."""
        return self._state

    def audit(
        self,
        x: "EvidenceRevocationList | bytes",
        now: object,
        min: object = 0,
    ) -> "EvidenceRevocationListAuditor":
        """Authenticate ``x`` and enforce monotone snapshot progress.

