        errors = []
        items = [
            self.e1, self.e1.to_bytes(), self.e2, self.e3,
            self.b012, self.b012.to_bytes(), b12, b23,
        ] * 6

        def worker(item):
            try:
                if isinstance(item, (EvidenceRevocationList, bytes)) and (
                    isinstance(item, EvidenceRevocationList)
                    or EvidenceRevocationListBundle.from_bytes(item)
                    and False
                ):
                    pass
            except Exception:
                pass
            try:
                if isinstance(item, EvidenceRevocationList):
                    auditor.audit(item, 12.0)
                elif isinstance(
                    item,  # type: ignore[unreachable]
                    EvidenceRevocationListBundle,
                ):
                    auditor.audit_bundle(item, 12.0)
                else:
                    # Bytes are ambiguous between the two records; only feed
                    # bundle bytes through the bundle entry here.
                    auditor.audit_bundle(item, 12.0)
            except ValueError:
                # Start-mismatch replays and superseded bundles must reject.
                pass
            except Exception as error:  # pragma: no cover - surfaced below
                errors.append(error)

        threads = [threading.Thread(target=worker, args=(item,)) for item in items]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()
        self.assertEqual(errors, [])
        self.assertEqual(auditor.checkpoint.sequence, 3)
        self.assertEqual(auditor.checkpoint, make_state(3, self.e3))

    def test_exactly_one_empty_start_bundle_wins_the_race(self):
        start = threading.Barrier(2)
        auditor = EvidenceRevocationListAuditor(KEY)
        outcomes = []

        def loser():
            start.wait()
            for _ in range(1000):
                try:
                    auditor.audit_bundle(self.b012, 11.0)
                except ValueError:
                    outcomes.append("rejected")

        def winner():
            start.wait()
            auditor.audit_bundle(self.b012, 11.0)
            outcomes.append("committed")

        threads = [
            threading.Thread(target=loser),
            threading.Thread(target=winner),
        ]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()
        self.assertEqual(outcomes.count("committed"), 1)
        self.assertTrue(outcomes.count("rejected") > 0)
        self.assertEqual(auditor.checkpoint.to_bytes(), self.b012.end)


if __name__ == "__main__":
    unittest.main()

